template <
  typename T,
  typename std::enable_if<
    std::is_base_of<T, types::IBranch>::value
  >::type*
>
std::pair<
  common::optional<std::shared_ptr<T> >,
  common::optional<DeserializationError>
> BranchFromSequence(
  xml_common::ReaderMergingText& reader
) {
  #ifdef DEBUG
  if (reader.node().kind() == xml_common::NodeKind::Error) {
    throw std::logic_error(
      "Unexpected unhandled XML error in BranchFromSequence. "
      "BranchFromSequence expects no reader error at entry."
    );
  }
  #endif

  common::optional<DeserializationError> error;

  error = SkipBof(reader);
  if (error.has_value()) {
    return NoInstanceAndDeserializationError<
      std::shared_ptr<T>
    >(
      std::move(*error)
    );
  }

  // region Initialization

  common::optional<std::wstring> the_identifier;

  common::optional<std::wstring> the_description;

  // endregion Initialization

  while (true) {
    error = SkipWhitespace(reader);
    if (error.has_value()) {
      return NoInstanceAndDeserializationError<
        std::shared_ptr<T>
      >(
        std::move(*error)
      );
    }

    if (reader.node().kind() == xml_common::NodeKind::Stop) {
      // NOTE (mristin):
      // We reached a closing element of an instance, so we know that
      // the sequence ended.
      break;
    } else if (reader.node().kind() != xml_common::NodeKind::Start) {
      return NoInstanceAndDeserializationErrorWithCause<
        std::shared_ptr<T>
      >(
        common::Concat(
          L"Expected a start element opening a property "
          L"of IBranch, but got ",
          xml_common::NodeToHumanReadableWstring(reader.node())
        )
      );
    }

    const std::string name(
      static_cast<  // NOLINT(cppcoreguidelines-pro-type-static-cast-downcast)
        const xml_common::StartNode&
      >(reader.node()).name
    );

    // NOTE (mristin):
    // We consume the start element.
    reader.Read();

    if (reader.node().kind() == xml_common::NodeKind::Error) {
      error = DeserializationErrorFromReader(reader);

      PrependElementSegmentToDeserializationError(
        name,
        *error
      );

      return NoInstanceAndDeserializationError<
        std::shared_ptr<T>
      >(
        std::move(*error)
      );
    }

    auto it = properties::kMapOfBranch.find(
      name
    );
    if (it == properties::kMapOfBranch.end()) {
      return NoInstanceAndDeserializationErrorWithCause<
        std::shared_ptr<T>
      >(
        common::Concat(
          L"Expected a start element opening a property "
          L"of IBranch, "
          L"but got a start element "
          L"which does not correspond to any of its properties: <",
          common::Utf8ToWstring(name),
          L">"
        )
      );
    }

    const properties::OfBranch property(
      it->second
    );

    switch (property) {
      case properties::OfBranch::kIdentifier: {
        std::tie(
          the_identifier,
          error
        ) = DeserializeWstring(reader);
        break;
      }
      case properties::OfBranch::kDescription: {
        std::tie(
          the_description,
          error
        ) = DeserializeWstring(reader);
        break;
      }
      default:
        throw std::logic_error(
          common::Concat(
            "Unexpected properties literal of "
            "properties::OfBranch: ",
            std::to_string(
              static_cast<uint32_t>(property)
            )
          )
        );
    }

    if (error.has_value()) {
      PrependElementSegmentToDeserializationError(
        name,
        *error
      );

      return NoInstanceAndDeserializationError<
        std::shared_ptr<T>
      >(
        std::move(*error)
      );
    }

    error = SkipWhitespace(reader);
    if (error.has_value()) {
      PrependElementSegmentToDeserializationError(
        name,
        *error
      );

      return NoInstanceAndDeserializationError<
        std::shared_ptr<T>
      >(
        std::move(*error)
      );
    }

    if (!xml_common::IsStopNodeWithName(reader.node(), name)) {
      error = DeserializationError(
        common::Concat(
          L"Expected a stop element </",
          common::Utf8ToWstring(name),
          L"> closing the property "
          L"of IBranch, but got ",
          xml_common::NodeToHumanReadableWstring(reader.node())
        )
      );

      PrependElementSegmentToDeserializationError(
        name,
        *error
      );

      return NoInstanceAndDeserializationError<
        std::shared_ptr<T>
      >(
        std::move(*error)
      );
    }

    // NOTE (mristin):
    // We consume the stop element.
    reader.Read();

    if (reader.node().kind() == xml_common::NodeKind::Error) {
      error = DeserializationErrorFromReader(reader);

      PrependElementSegmentToDeserializationError(
        name,
        *error
      );

      return NoInstanceAndDeserializationError<
        std::shared_ptr<T>
      >(
        std::move(*error)
      );
    }
  }

  // region Check required properties

  if (!the_identifier.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<T>
    >(
      L"The required property identifier is missing"
    );
  }

  if (!the_description.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<T>
    >(
      L"The required property description is missing"
    );
  }

  // endregion Check required properties

  return std::make_pair(
    common::make_optional<
      std::shared_ptr<T>
    >(
      // NOTE (mristin):
      // We deliberately do not use std::make_shared here to avoid an unnecessary
      // upcast.
      new types::Branch(
        std::move(*the_identifier),
        std::move(*the_description)
      )
    ),
    common::nullopt
  );
}

